var c = $input.first().json.data || $input.first().json;
var counter = Number(c.counterofferAmount);
var mao = Number(c.protectedMAO);
var current = Number(c.currentOfferAmount || 0);
var repair = Number(c.estimatedRepairs || 0);
var arv = Number(c.arv || 0);
var gap = Number.isFinite(counter) && Number.isFinite(current) ? counter - current : null;
var pctMao = Number.isFinite(counter) && mao > 0 ? counter / mao : null;
var decision = 'human_review';
if (!Number.isFinite(counter) || counter <= 0 || !Number.isFinite(mao) || mao <= 0) decision = 'human_review';
else if (counter <= mao && counter <= current) decision = 'accept_or_contract';
else if (counter <= mao) decision = 'revised_offer';
else if (counter > mao) decision = 'walk_away_or_reengage';
var idempotencyKey = 'wf375:' + String(c.decisionId || c.activityId || '') + ':' + String(counter);
return [{ json: { ...c, counterofferAmount: counter, currentOfferAmount: current, protectedMAO: mao, estimatedRepairs: repair, arv: arv, counterGap: gap, counterToMAORatio: pctMao, evaluationDecision: decision, humanReviewRequired: decision === 'human_review', idempotencyKey: idempotencyKey } }];

var d = $input.first().json;
var invalid = !Number.isFinite(Number(d.counterofferAmount)) || Number(d.counterofferAmount) <= 0;
var protectedState = ['closed','cancelled','disputed'].indexOf(String(d.dealStatus || '').toLowerCase()) !== -1;
var blocked = invalid || protectedState;
return [{ json: { ...d, blocked: blocked, blockedReason: invalid ? 'invalid_counteroffer' : protectedState ? 'deal_state_protected' : null } }];
